    {
      "path": "src/finance.py",
      "language": "python",
      "type": "MCP tool definitions via @mcp.tool() decorators"
    }
  ],
  "mcp_tools": [
    {
      "name": "view_account",
      "description": "View details for an account",
      "parameters": {"account_id": "str (required)"}
    },
    {
      "name": "departments",
      "description": "List all departments",
      "parameters": {}
    },
    {
      "name": "accounts",
      "description": "List transactions",
      "parameters": {"account_id": "str (optional)", "department_id": "str (optional)"}
    },
    {
      "name": "employees",
      "description": "List employees",
      "parameters": {"department_id": "str (optional)"}
    },
    {
      "name": "salary_advance",
      "description": "Request a salary advance",
      "parameters": {"employee_id": "str (required)", "amount": "float (required)", "reason": "str (required)"}
    },
    {
      "name": "budgets",
      "description": "List all budgets",
      "parameters": {}
    },
    {
      "name": "budget",
      "description": "View a specific budget",
      "parameters": {"budget_id": "str (required)"}
    },
    {
      "name": "spending",
      "description": "View spending",
      "parameters": {"budget_id": "str (required)"}
    },
    {
